/* QZ-UI-03: offline interaction design only. All state is session-local. */
(() => {
'use strict';
const D=window.QZ_DEMO;
const symbols={home:'M3 11 12 3l9 8M5 10v10h5v-6h4v6h5V10',book:'M4 4h7a3 3 0 0 1 1 1 3 3 0 0 1 1-1h7v16h-7a3 3 0 0 0-1 1 3 3 0 0 0-1-1H4ZM12 5v16',plus:'M12 5v14M5 12h14',records:'M5 3h14v18H5ZM8 7h8M8 11h8M8 15h5',excel:'M5 3h14v18H5ZM8 7h8M8 11h8M8 15h8M12 7v10',library:'M4 6h16v4H4ZM4 14h16v4H4ZM8 6v4M16 14v4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',arrow:'M5 12h14M13 6l6 6-6 6',back:'M19 12H5M11 6l-6 6 6 6',check:'m5 12 4 4L19 6',close:'m6 6 12 12M18 6 6 18',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14Zm5 12 6 6',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18ZM12 10v6M12 7v1',download:'M12 3v12M7 10l5 5 5-5M4 17v4h16v-4',source:'M5 5h6v6H5ZM13 13h6v6h-6ZM8 11v5h5'};
const sprite=`<svg xmlns="http://www.w3.org/2000/svg">${Object.entries(symbols).map(([id,d])=>`<symbol id="qz-icon-${id}" viewBox="0 0 24 24"><path d="${d}" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></symbol>`).join('')}</svg>`;
document.getElementById('svg-sprite').innerHTML=sprite;
const S={product:'ec',page:'home',scenario:'normal',search:'',status:'all',support:'all',pageNo:1,tab:0,selected:null,excelLoaded:false,excelChecked:false,excelDone:false,fileName:'',paramSearch:'',density:'舒适',toastTimer:null};
const sessions={};
const app=document.getElementById('app');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<svg class="icon" aria-hidden="true"><use href="#qz-icon-${n}"/></svg>`;
const p=()=>D.products[S.product];
const session=()=>sessions[S.product]||(sessions[S.product]={form:{name:'青舟示例企业',period:'2026',quantity:'10000',energy:'75000',flow:'120',head:'30',power:'15'},sources:D.makeSources(),nextSource:100,checked:false,result:false,error:false,recordSeq:10000,records:D.makeRecords(S.product),workspaces:[]});
const count=()=>S.scenario==='long'?420:36;
const standards=()=>S.scenario==='empty'?[]:D.makeStandards(S.product,count());
const records=()=>S.scenario==='empty'?[]:S.scenario==='long'?session().records.concat(D.makeRecords(S.product,294).map((r,i)=>({...r,id:`extra-${i}`,name:`长列表演示 ${i+127}`}))):session().records;
const btn=(text,action,style='secondary',extra='')=>`<button class="btn ${style}" data-action="${action}" ${extra}>${text}</button>`;
const notice=(text,type='info')=>`<div class="notice ${type}" role="${type==='error'?'alert':'note'}">${icon(type==='error'?'info':'info')}<span>${text}</span></div>`;
const brand=()=>`<img class="brand-logo" src="assets/qingzhou-logo.png" alt="青舟节能真实 LOGO"><div class="brand-copy">工业能源软件 · ${p().short}</div>`;
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.hidden=false;clearTimeout(S.toastTimer);S.toastTimer=setTimeout(()=>el.hidden=true,5000);}
function topbar(){return `<header class="topbar"><label class="product-switch">产品切换 <select id="product" aria-label="切换软件">${Object.entries(D.products).map(([key,v])=>`<option value="${key}" ${S.product===key?'selected':''}>${v.short} · ${v.name}</option>`).join('')}</select></label><div class="top-actions"><span class="demo-badge">交互原型 · 演示数据</span>${S.page==='home'?btn(`${icon('settings')}设置`,'home-settings'):''}</div></header>`;}
function sidebar(){const items=[['home','首页','home',true],['standards','标准库','book',true],['create',p().create,'plus',true],['excel','Excel导入','excel',p().excel],['records',p().records,'records',true]];if(p().library)items.push(['library',p().library,'library',p().lib]);return `<aside class="sidebar" aria-label="业务导航"><div>${brand()}</div><nav class="nav-list">${items.map(([route,label,ico,enabled])=>`<button class="nav-btn ${S.page===route||S.page===route+'-detail'?'active':''}" data-action="navigate" data-page="${route}" ${enabled?'':`disabled title="当前未开放"`} ${S.page===route?'aria-current="page"':''}>${icon(ico)}<span>${label}${enabled?'':'<small>未开放</small>'}</span></button>`).join('')}</nav><div class="nav-footer"><div class="brand-copy">离线演示 · 不连接业务数据</div><button class="nav-btn ${S.page==='settings'?'active':''}" data-action="navigate" data-page="settings">${icon('settings')}<span>设置</span></button></div></aside>`;}
function scenarios(){return `<div class="scenario-bar"><span>原型验证</span><label>数据场景 <select id="scenario" aria-label="数据场景">${[['normal','正常示例'],['long','长表格 / 长表单'],['empty','空状态'],['error','输入错误']].map(([value,text])=>`<option value="${value}" ${S.scenario===value?'selected':''}>${text}</option>`).join('')}</select></label><span>所有状态仅为交互演示</span>${S.product==='ec'?btn('预览未开放 Excel 设计','preview-excel','small'):''}</div>`;}
function header(title,desc='',actions=''){return `<div class="page-header"><div><div class="eyebrow">${p().short} / ${S.page.includes('detail')?'详情':'工作台'}</div><h1 class="page-title" tabindex="-1">${esc(title)}</h1><p class="page-subtitle">${desc}</p></div><div class="header-actions">${actions}</div></div>`;}
function empty(message='没有符合条件的演示数据'){return `<div class="empty-state"><div class="empty-icon">${icon('search')}</div><h2>${message}</h2><p>尝试其他关键词、状态，或切回“正常示例”。真实数据未接入。</p>${btn('重置筛选','reset-filters')}</div>`;}
function pagination(total){const pages=Math.max(1,Math.ceil(total/12));S.pageNo=Math.min(S.pageNo,pages);return `<div class="pagination"><span>共 ${total} 条 · 每页 12 条 · ${S.pageNo} / ${pages}</span><div>${btn('上一页','prev','small',S.pageNo===1?'disabled':'')}${btn('下一页','next','small',S.pageNo===pages?'disabled':'')}</div></div>`;}
function home(){const entries=[['standards','标准库','查找标准，阅读适用范围和要求。','book',true],['create',p().create,'填写业务数据，检查后查看结果示意。','plus',true],['records',p().records,'浏览完整记录列表，查看保存时的快照。','records',true],['excel','Excel导入',S.product==='ec'?'当前未开放，后续独立任务评估。':S.product==='eq'?'模板、导入检查与批量处理结构。':'只读预览，不自动创建正式记录。','excel',p().excel]];if(p().library)entries.push(['library',p().library,S.product==='ec'?'当前未开放。':'浏览演示参数与因子，不作为核算来源。','library',p().lib]);return `${header(p().name,'青舟工业能源软件 · 从标准到业务，清楚地完成每一步')}<div class="home-hero"><div class="home-brand">${brand()}</div><div><span class="eyebrow">当前参考标准</span><h2>${esc(p().standard)}</h2><p>${esc(p().intro)}</p><span class="badge muted">本页无左侧导航</span></div></div><div class="entry-grid">${entries.map(([route,label,desc,ico,on],i)=>`<button class="entry-card" data-action="navigate" data-page="${route}" ${on?'':'disabled'}><div class="entry-icon">${icon(ico)}</div><span class="entry-number">0${i+1}</span><span class="entry-label">${label}${on?'':' · 未开放'}</span><span class="entry-description">${desc}</span>${icon('arrow')}</button>`).join('')}</div><section class="card"><div class="card-header"><h2>最近工作</h2><span class="badge muted">演示快照</span></div><div class="card-body recent-list">${records().slice(0,3).map(r=>`<button class="row-link" data-action="open-record" data-id="${r.id}"><span>${esc(r.name)}</span><span>${r.date} ${icon('arrow')}</span></button>`).join('')||'<p>暂无演示记录。</p>'}</div></section><footer class="home-footer"><span>设置独立于主要业务入口</span>${btn(`${icon('settings')} 软件设置`,'home-settings')}</footer>`;}
function standardsPage(){const rows=standards().filter(r=>(r.code+r.name).toLowerCase().includes(S.search.toLowerCase())&&(S.status==='all'||r.status===S.status)&&(S.support==='all'||(S.support==='reference'?r.id===0:r.id!==0)));const paging=pagination(rows.length);return `${header('标准库','标准状态与软件支持分别展示，收录不代表正式支持。')}<div class="toolbar"><label class="field">关键词<input id="search" placeholder="标准编号或名称" value="${esc(S.search)}"></label><label class="field">标准状态<select id="status">${['all','现行','即将实施','已废止'].map(v=>`<option value="${v}" ${v===S.status?'selected':''}>${v==='all'?'全部状态':v}</option>`).join('')}</select></label><label class="field">软件支持<select id="support"><option value="all">全部支持状态</option><option value="reference" ${S.support==='reference'?'selected':''}>参考标准（演示）</option><option value="catalog" ${S.support==='catalog'?'selected':''}>仅演示目录</option></select></label>${btn('重置','reset-filters')}</div><p class="page-subtitle">此列表含合成示例，状态、日期和支持信息不是正式事实声明。</p>${rows.length?`<div class="table-wrap" tabindex="0" aria-label="标准五列表格，可横向滚动"><table class="data-table"><thead><tr><th>标准编号</th><th>标准名称</th><th>标准状态</th><th>实施日期</th><th>软件支持</th></tr></thead><tbody>${rows.slice((S.pageNo-1)*12,S.pageNo*12).map(r=>`<tr><td><button class="link-btn" data-action="open-standard" data-id="${r.id}">${esc(r.code)}</button></td><td>${esc(r.name)}</td><td><span class="badge ${r.status==='现行'?'success':'warning'}">${r.status}（演示）</span></td><td>${r.date}</td><td>${r.support}</td></tr>`).join('')}</tbody></table></div>${paging}`:empty()}`;}
function tabs(labels){return `<div class="tabs" role="tablist" aria-label="详情页签">${labels.map((label,i)=>`<button class="tab" role="tab" id="tab-${i}" aria-controls="detail-panel" aria-selected="${S.tab===i}" tabindex="${S.tab===i?'0':'-1'}" data-action="tab" data-tab="${i}">${label}</button>`).join('')}</div>`;}
function standardDetail(){const r=D.makeStandards(S.product,420).find(v=>v.id===Number(S.selected));if(!r){S.page='standards';return standardsPage();}const content=[`<dl class="definition-list"><dt>标准编号</dt><dd>${esc(r.code)}</dd><dt>标准名称</dt><dd>${esc(r.name)}</dd><dt>标准状态</dt><dd>${r.status}（演示）</dd><dt>发布日期</dt><dd>日期待真实目录接入</dd><dt>实施日期</dt><dd>${r.date}</dd><dt>软件支持</dt><dd>${r.support}</dd></dl>`,`<h2>标准适用范围</h2><p>${r.scope}</p><h2>软件支持范围</h2><p>此原型只演示浏览行为，不声明任何新增 Capability 或正式支持范围。</p>`,`<h2>标准要求展示示例</h2><p>这里用于验证条款、指标与可读依据的展示层级。未录入正式标准条款、限值或等级规则。</p><div class="card">${notice('正式要求与解释应由业务仓已经验证的标准数据提供；本原型不构成标准映射。')}</div>`][S.tab];return `${header(r.name,`${r.code} · 详情为展示示例`,btn(`${icon('back')} 返回标准库`,'back-standard'))}${tabs(['基本信息','适用范围','标准要求'])}<section class="card tab-panel" id="detail-panel" role="tabpanel" aria-labelledby="tab-${S.tab}"><div class="card-body">${content}</div></section><div class="header-actions">${btn('查看标准原文','original')}${r.id===0?btn(p().create,'start-standard','primary'):btn('当前未提供业务入口','noop','secondary','disabled')}</div>`;}
function recordsPage(){const rows=records().filter(r=>(r.name+r.id+r.standard).toLowerCase().includes(S.search.toLowerCase()));const paging=pagination(rows.length);return `${header(p().records,'全部演示记录可分页访问，详情以保存时快照呈现。')}<div class="toolbar"><label class="field">搜索记录<input id="search" placeholder="名称、编号或标准" value="${esc(S.search)}"></label>${btn('重置','reset-filters')}</div>${rows.length?`<div class="table-wrap" tabindex="0" aria-label="记录列表"><table class="data-table"><thead><tr><th>业务名称</th><th>标准</th><th>保存时间</th><th>状态</th><th>操作</th></tr></thead><tbody>${rows.slice((S.pageNo-1)*12,S.pageNo*12).map(r=>`<tr><td>${esc(r.name)}<small>${r.id}</small></td><td>${esc(r.standard)}</td><td>${r.date}</td><td><span class="badge muted">${r.status}</span></td><td>${btn('查看详情','open-record','small',`data-id="${r.id}"`)}</td></tr>`).join('')}</tbody></table></div>${paging}`:empty('暂无演示记录')}`;}
function recordDetail(){const r=records().find(v=>v.id===S.selected)||session().records.find(v=>v.id===S.selected);if(!r){S.page='records';return recordsPage();}return `${header(r.name,'独立详情 · 只读演示快照，不按当前标准重算。',btn(`${icon('back')} 返回记录列表`,'back-record'))}${tabs(['基本信息与结果','输入数据与计算依据'])}<section class="card tab-panel" id="detail-panel" role="tabpanel" aria-labelledby="tab-${S.tab}"><div class="card-body">${S.tab===0?`<dl class="definition-list"><dt>名称</dt><dd>${esc(r.name)}</dd><dt>标准</dt><dd>${esc(r.standard)}</dd><dt>保存时间</dt><dd>${r.date}</dd><dt>状态</dt><dd>${r.status} · 非正式判定</dd></dl><div class="result-card"><div class="metric-label">演示值 · 非计算输出</div><div class="metric-value">${r.value} <small>${r.unit}</small></div><p>只展示结果卡片结构，不代表该标准下的正确结论。</p></div>`:`<h2>输入快照</h2><dl class="definition-list">${r.input.map(([a,b])=>`<dt>${esc(a)}</dt><dd>${esc(b)}</dd>`).join('')}</dl><h2>计算依据展示结构</h2><p>业务字段 → 参数 → 计算说明 → 判定依据。原型未接入正式公式、规则或标准证据，不生成正式依据。</p>${S.product==='ghg'?'<p>工作区是可编辑工作状态；本记录为独立演示快照，两者不合并。</p>':''}`}</div></section>`;}
function input(label,key,value,options=''){return `<label class="field">${label}<input id="field-${key}" data-form="${key}" value="${esc(value)}" ${options}></label>`;}
function sourceCard(src,i){return `<section class="source-card" data-source-id="${src.id}"><div class="source-header"><h3>排放源 ${i+1} · ${esc(src.type)}</h3>${btn('移除','remove-source','small',`data-id="${src.id}"`)}</div><div class="source-grid"><label class="field">来源类型（演示）<select id="${src.id}-type" data-source="${src.id}" data-key="type">${['燃料燃烧','购入电力','购入热力','生产过程'].map(t=>`<option ${t===src.type?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">名称<input id="${src.id}-name" data-source="${src.id}" data-key="name" value="${esc(src.name)}"></label><label class="field">活动量<input id="${src.id}-amount" data-source="${src.id}" data-key="amount" value="${esc(src.amount)}" inputmode="decimal"></label><label class="field">单位（演示）<select id="${src.id}-unit" data-source="${src.id}" data-key="unit">${['t','MWh','GJ'].map(t=>`<option ${t===src.unit?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">备注<textarea id="${src.id}-note" data-source="${src.id}" data-key="note">${esc(src.note)}</textarea></label></div></section>`;}
function createPage(){const a=session();return `${header(p().create,'五类功能按业务分区组织，不强制相同表单或页签。')}<div class="long-form-layout"><nav class="form-toc" aria-label="表单分区"><span class="eyebrow">本次工作</span>${['基本信息','业务数据','数据检查','计算','结果'].map((t,i)=>`<a href="#section-${i}">${String(i+1).padStart(2,'0')} ${t}</a>`).join('')}</nav><div class="form-content"><section class="card form-section" id="section-0"><div class="card-header"><h2>01 基本信息</h2><span class="badge muted">演示输入</span></div><div class="card-body field-grid">${input('业务对象 / 企业名称','name',a.form.name,'required')}${input('业务期间','period',a.form.period)}<label class="field">参考标准<input readonly value="${esc(p().standard)}"></label></div></section><section class="card form-section" id="section-1"><div class="card-header"><h2>02 业务数据</h2>${S.product==='ghg'?btn(`${icon('plus')} 添加排放源`,'add-source'):''}</div><div class="card-body">${S.product==='ghg'?`${notice('来源类型与字段仅为动态交互示例，不定义标准核算边界。切换类型保留现有输入，具体策略待确认。')}<div id="sources">${a.sources.map(sourceCard).join('')||empty('尚未添加排放源')}</div>`:`<div class="field-grid">${S.product==='ec'?input('产品产量（演示 t）','quantity',a.form.quantity,'inputmode="decimal"')+input('能源使用量（演示 kWh）','energy',a.form.energy,'inputmode="decimal"'):input('流量（演示 m³/h）','flow',a.form.flow,'inputmode="decimal"')+input('扬程（演示 m）','head',a.form.head,'inputmode="decimal"')+input('轴功率（演示 kW）','power',a.form.power,'inputmode="decimal"')}</div>`}</div></section><section class="card form-section" id="section-2"><div class="card-header"><h2>03 数据检查</h2>${btn('检查演示输入','check-form')}</div><div class="card-body" id="checks">${a.error?notice(a.error,'error'):a.checked?notice('演示输入结构检查通过。未验证标准适用范围、业务数值或正式算法。'):notice('只检查演示字段完整性和数值格式，不执行业务校验。')}</div></section><section class="card form-section" id="section-3"><div class="card-header"><h2>04 计算</h2>${btn('演示计算交互','calculate','primary')}</div><div class="card-body"><p>点击后仅展示示意结果，未调用 Calculator，不执行标准判定。</p>${S.product==='eq'?'<p>沿用“无草稿、无额外保存步骤”的设计边界；有效演示完成后自动增加一条演示记录。</p>':''}</div></section><section class="card form-section" id="section-4"><div class="card-header"><h2>05 结果</h2></div><div class="card-body">${a.result?`<div class="result-grid"><div class="result-card"><div class="metric-label">演示值 · 非计算输出</div><div class="metric-value">${p().value} <small>${p().unit}</small></div></div><div><h3>交互演示已完成</h3><p>不提供正式等级、达标结论或真实核算结果。</p><span class="badge warning">不可用于正式判定</span></div></div>`:'<div class="empty-state"><h3>完成检查后查看结果示意</h3><p>未生成正式结果。</p></div>'}${a.result&&S.product!=='eq'?btn('保存演示记录','save-demo','secondary'):''}</div></section>${S.product==='ghg'?`<section class="card"><div class="card-header"><h2>工作区与记录分别管理</h2>${btn('保存内存工作区示例','save-workspace')}</div><div class="card-body"><p>此处模拟已有工作区能力，仅保留在当前原型内存；刷新即丢失。不会生成正式记录。</p><div class="workspace-list">${a.workspaces.map((w,i)=>btn(`打开演示工作区 ${i+1}`,'open-workspace','small',`data-id="${i}"`)).join('')||'<span>暂无内存工作区</span>'}</div></div></section>`:''}</div></div>`;}
function excelPage(){const enabled=p().excel;const rows=S.excelLoaded?Array.from({length:S.scenario==='long'?80:6},(_,i)=>({name:`演示单元 ${i+1}`,input:S.scenario==='error'&&i===0?'缺失':'演示输入',status:S.scenario==='error'&&i===0?'需补充（演示）':'结构示例'})):[];return `${header('Excel导入',S.product==='eq'?'批量工作流设计 · 原型不解析真实 XLSX。':S.product==='ghg'?'只读预览设计，不自动创建正式记录。':'未开放能力的禁用设计预览，不表示开放。')}${notice(enabled?'选择真实文件只显示文件名和大小；预览、检查与处理均使用合成演示数据。':'ECQuota Excel导入当前未开放。此页面仅供原型评审，所有业务操作禁用。','warning')}<div class="excel-grid"><section class="card excel-region" data-region="1"><div class="card-header"><span class="region-number">01</span><h2>模板与说明</h2></div><div class="card-body"><p>四区域标题为推荐方案。${S.product==='ghg'?'本次只演示预览，不模拟新增的保存项目 / 正式核算链路。':'不提供真实标准模板。'}</p>${btn('下载演示 CSV 模板','template','secondary',enabled?'':'disabled')}</div></section><section class="card excel-region" data-region="2"><div class="card-header"><span class="region-number">02</span><h2>文件选择</h2></div><div class="card-body"><label class="field">选择工作簿（仅显示文件信息）<input id="excel-file" type="file" accept=".xlsx,.xls,.csv" ${enabled?'':'disabled'}></label><p id="file-meta">${esc(S.fileName||'尚未选择文件')}</p>${btn('加载演示工作簿','load-excel','secondary',enabled?'':'disabled')}</div></section><section class="card excel-region" data-region="3"><div class="card-header"><span class="region-number">03</span><h2>数据预览与检查</h2></div><div class="card-body">${rows.length?`<div class="table-wrap" tabindex="0"><table class="data-table"><thead><tr><th>演示单元</th><th>输入</th><th>检查状态</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.name}</td><td>${r.input}</td><td>${r.status}</td></tr>`).join('')}</tbody></table></div>`:'<p>先加载演示工作簿，验证列表与检查反馈。</p>'}${btn(S.product==='ghg'?'检查预览结构':'导入检查演示','check-excel','secondary',enabled&&S.excelLoaded?'':'disabled')}${S.excelChecked?notice(S.scenario==='error'?'演示第一行缺少输入，请切换正常示例后重新加载。':'结构检查反馈已生成，仅为演示。',S.scenario==='error'?'error':'info'):''}</div></section><section class="card excel-region" data-region="4"><div class="card-header"><span class="region-number">04</span><h2>处理结果</h2></div><div class="card-body">${S.product==='eq'?`${btn('演示批量评价','batch','primary',S.excelChecked&&S.scenario!=='error'?'':'disabled')}<p>示意批次总结，不输出正式评价结论。</p>${S.excelDone?`${notice('演示批次完成，已增加一条内存演示批次记录。')}${btn('下载演示结果 CSV','export-csv')}`:''}`:S.product==='ghg'?'<p>只读预览：不创建工作区或正式记录。最新业务仓的明确保存项目路径尚待设计映射确认。</p><span class="badge muted">无正式核算动作</span>':'<p>当前未开放，后续独立任务评估。</p>'}</div></section></div>`;}
function libraryPage(){const rows=S.scenario==='empty'?[]:D.parameters.filter(r=>(r.name+r.standard).includes(S.paramSearch));return `${header(p().library||'参数库','只读演示浏览；数值不作为正式核算来源。')}<div class="toolbar"><label class="field">搜索参数<input id="param-search" value="${esc(S.paramSearch)}" placeholder="名称或标准"></label></div>${rows.length?`<div class="table-wrap" tabindex="0"><table class="data-table"><thead><tr><th>名称</th><th>适用标准</th><th>示意值</th><th>单位</th><th>操作</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.name}</td><td>${r.standard}</td><td>${r.value}</td><td>${r.unit}</td><td>${btn('查看说明','parameter','small',`data-id="${r.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('暂无演示参数')}`;}
function settingsContent(){return `${S.product==='ghg'?notice('GHGTOOL 当前设置页仍为占位。下列原型选项为推荐设计，不表示已实现业务功能。','warning'):''}<div class="settings-grid"><section class="card"><div class="card-header"><h2>界面偏好（原型内存）</h2></div><div class="card-body"><label class="field">信息密度<select id="density">${['舒适','紧凑'].map(v=>`<option ${S.density===v?'selected':''}>${v}</option>`).join('')}</select></label><p>仅改变本原型间距，刷新后恢复；不是系统或业务配置。</p></div></section><section class="card"><div class="card-header"><h2>关于本原型</h2></div><div class="card-body"><p>QZ-UI-03 · Phase 2</p><p>本地离线运行 / 无外部依赖 / 不连接数据库</p><p>颜色、尺寸与交互细节均为可演进方案。</p></div></section></div>`;}
function render(){const focusId=document.activeElement?.id;const caret=document.activeElement?.selectionStart;const y=window.scrollY;let content;switch(S.page){case'home':content=home();break;case'standards':content=standardsPage();break;case'standards-detail':content=standardDetail();break;case'records':content=recordsPage();break;case'records-detail':content=recordDetail();break;case'create':content=createPage();break;case'excel':content=excelPage();break;case'library':content=libraryPage();break;case'settings':content=header('设置','当前页面为视觉与交互方案，不修改真实软件配置。')+settingsContent();break;default:content=home();}app.innerHTML=`<div class="${S.page==='home'?'home-screen':'app-shell'}">${S.page==='home'?'':sidebar()}<div class="workspace">${topbar()}<main id="main">${scenarios()}${content}</main><footer class="prototype-footer">全部业务数据、日期、数值与结果均为演示 · 未执行正式标准判定</footer></div></div>`;document.body.classList.toggle('compact',S.density==='紧凑');if(focusId){const node=document.getElementById(focusId);if(node){node.focus({preventScroll:true});if(typeof caret==='number'&&node.setSelectionRange&&node.type!=='number')try{node.setSelectionRange(caret,caret);}catch{}}}window.scrollTo(0,y);}
function navigate(page){if((page==='excel'&&!p().excel)||(page==='library'&&!p().lib))return toast('当前能力未开放。');S.page=page;S.search='';S.status='all';S.support='all';S.pageNo=1;S.selected=null;S.tab=0;render();window.scrollTo(0,0);document.querySelector('.page-title')?.focus({preventScroll:true});}
function validate(){const a=session();if(!a.form.name.trim())return '请填写业务对象 / 企业名称。';const fields=S.product==='ec'?['quantity','energy']:S.product==='eq'?['flow','head','power']:[];for(const key of fields)if(!/^\d+(\.\d+)?$/.test(a.form[key])||Number(a.form[key])<=0)return '演示数值需要填写大于零的十进制数字；这不是标准业务校验。';if(S.product==='ghg'){if(!a.sources.length)return '请至少添加一个演示排放源。';for(const src of a.sources)if(!src.name.trim()||!/^\d+(\.\d+)?$/.test(src.amount)||Number(src.amount)<=0)return '请补齐排放源名称及大于零的活动量（演示格式检查）。';}return false;}
function addRecord(name){const a=session();a.records.unshift({id:`demo-${S.product}-${a.recordSeq++}`,name:name||`${a.form.name} · 演示${p().verb}`,standard:p().standard,date:'当前原型会话（演示）',status:'演示完成',value:p().value,unit:p().unit,input:[['对象',a.form.name],['期间',a.form.period],['说明','内存演示快照；未计算正式业务结果']]});}
function download(name,text){const url=URL.createObjectURL(new Blob(['\ufeff',text],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function settingsDialog(){const dialog=document.getElementById('settings-dialog');dialog.innerHTML=`<div class="card-header"><h2 id="dialog-title">设置 · 推荐弹窗方案，待确认</h2>${btn('关闭','close-dialog')}</div><div class="card-body">${settingsContent()}</div>`;dialog.showModal();}
function handle(action,target){const a=session();switch(action){case'navigate':navigate(target.dataset.page);return;case'home-settings':settingsDialog();return;case'close-dialog':document.getElementById('settings-dialog').close();return;case'open-standard':S.selected=Number(target.dataset.id);S.page='standards-detail';S.tab=0;break;case'open-record':S.selected=target.dataset.id;S.page='records-detail';S.tab=0;break;case'back-standard':S.page='standards';break;case'back-record':S.page='records';break;case'tab':S.tab=Number(target.dataset.tab);break;case'prev':S.pageNo--;break;case'next':S.pageNo++;break;case'reset-filters':S.search='';S.status='all';S.support='all';S.pageNo=1;S.paramSearch='';S.scenario='normal';break;case'original':toast('本原型未附正式标准原文。后续业务实现使用已有合法原文资源。');return;case'start-standard':navigate('create');return;case'preview-excel':S.page='excel';S.excelLoaded=false;S.excelChecked=false;break;case'add-source':a.sources.push({id:`source-${a.nextSource++}`,type:'燃料燃烧',name:'',amount:'',unit:'t',note:''});a.checked=false;a.result=false;break;case'remove-source':a.sources=a.sources.filter(s=>s.id!==target.dataset.id);a.checked=false;a.result=false;break;case'check-form':a.error=validate();a.checked=!a.error;a.result=false;break;case'calculate':a.error=validate();a.checked=!a.error;if(!a.error){a.result=true;if(S.product==='eq')addRecord();toast('仅展示示意结果，未执行正式计算。');}break;case'save-demo':if(a.result&&!validate()){addRecord();toast('已保存内存演示记录，刷新后丢失。');}return;case'save-workspace':a.workspaces.push(JSON.parse(JSON.stringify({form:a.form,sources:a.sources})));toast('工作区示例仅保存在原型内存，不生成正式记录。');break;case'open-workspace':{const w=a.workspaces[Number(target.dataset.id)];if(w){a.form={...w.form};a.sources=JSON.parse(JSON.stringify(w.sources));a.checked=false;a.result=false;}}break;case'load-excel':if(!p().excel)return;S.excelLoaded=true;S.excelChecked=false;S.excelDone=false;break;case'check-excel':if(p().excel&&S.excelLoaded)S.excelChecked=true;break;case'batch':if(S.product==='eq'&&S.excelChecked&&S.scenario!=='error'){S.excelDone=true;addRecord('Excel 演示批次总结 · 非正式评价');}break;case'template':download('仅演示模板.csv','演示对象,演示输入,说明\n示例设备,100,不是真实标准模板\n');return;case'export-csv':if(S.product==='eq'&&S.excelDone)download('仅演示结果.csv','演示单元,交互状态,说明\n示例设备,演示完成,未执行正式计算或判定\n');return;case'parameter':{const r=D.parameters.find(v=>v.id===Number(target.dataset.id));if(!r)return;const dialog=document.getElementById('settings-dialog');dialog.innerHTML=`<div class="card-header"><h2 id="dialog-title">${esc(r.name)} · 演示参数详情</h2>${btn('关闭','close-dialog')}</div><div class="card-body">${notice('只读演示，不作为正式核算来源。')}<dl class="detail-grid"><dt>适用标准</dt><dd>${esc(r.standard)}</dd><dt>示意值</dt><dd>${esc(r.value)}</dd><dt>单位</dt><dd>${esc(r.unit)}</dd><dt>说明</dt><dd>${esc(r.note)}</dd></dl></div>`;dialog.showModal();return;}default:return;}render();if(['open-standard','open-record','back-standard','back-record'].includes(action)){window.scrollTo(0,0);document.querySelector('.page-title')?.focus({preventScroll:true});}if(action==='tab')document.getElementById(`tab-${S.tab}`)?.focus({preventScroll:true});if(action==='check-form'||action==='calculate')document.getElementById(a.error?'checks':'section-4')?.scrollIntoView({block:'center',behavior:'auto'});}
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(b&&!b.disabled)handle(b.dataset.action,b);});
document.addEventListener('input',event=>{const t=event.target;const a=session();const hadFeedback=a.result||a.checked||a.error;if(t.dataset.form){a.form[t.dataset.form]=t.value;a.checked=false;a.result=false;a.error=false;}if(t.dataset.source){const source=a.sources.find(s=>s.id===t.dataset.source);if(source)source[t.dataset.key]=t.value;a.checked=false;a.result=false;}if(hadFeedback&&(t.dataset.form||t.dataset.source))render();if(t.id==='search'){S.search=t.value;S.pageNo=1;render();}if(t.id==='param-search'){S.paramSearch=t.value;render();}});
document.addEventListener('change',event=>{const t=event.target;if(t.id==='product'){document.getElementById('settings-dialog').close();S.product=t.value;S.scenario='normal';S.excelLoaded=false;S.excelChecked=false;S.excelDone=false;S.fileName='';navigate('home');}if(t.id==='scenario'){S.scenario=t.value;S.pageNo=1;S.search='';S.status='all';S.support='all';S.paramSearch='';S.excelLoaded=false;S.excelChecked=false;S.excelDone=false;const a=session();a.result=false;a.checked=false;a.error=false;if(t.value==='long'&&S.product==='ghg')a.sources=D.makeSources(18);if(t.value==='error'){a.form.name='';if(S.product==='ghg')a.sources=D.makeSources(2).map((s,i)=>i===0?{...s,amount:''}:s);}if(t.value==='normal'){a.form.name='青舟示例企业';if(S.product==='ghg')a.sources=D.makeSources(2);}render();}if(t.id==='status'||t.id==='support'){S[t.id]=t.value;S.pageNo=1;render();}if(t.id==='density'){S.density=t.value;render();}if(t.id==='excel-file'){const f=t.files[0];S.fileName=f?`${f.name} · ${f.size} 字节（未解析）`:'';S.excelLoaded=false;S.excelChecked=false;S.excelDone=false;render();}});
document.addEventListener('keydown',event=>{if(event.target.getAttribute('role')==='tab'&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const total=document.querySelectorAll('[role=tab]').length;S.tab=event.key==='Home'?0:event.key==='End'?total-1:(S.tab+(event.key==='ArrowRight'?1:-1)+total)%total;render();document.getElementById(`tab-${S.tab}`).focus();}});
render();
})();
